"""Build the standalone motion study from the same SVG and CSS as the product."""

import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[3]
SVG = (ROOT / "apps/pulse/public/morning-logo.svg").read_text()
CSS = (ROOT / "apps/pulse/src/brand.css").read_text()

HTML = r"""<!doctype html>
<html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Morning · 分层 Logo</title><link rel="icon" href="/mark.svg?v=layered-sunrise" type="image/svg+xml">
<style>
*{box-sizing:border-box}body{margin:0;background:#f4f1eb;color:#30312d;font-family:-apple-system,BlinkMacSystemFont,"PingFang SC",sans-serif}button,input{font:inherit}button{cursor:pointer}button:focus-visible,input:focus-visible,a:focus-visible{outline:2px solid #a7482b;outline-offset:4px}button{border:1px solid #dcd7ce;background:#fffefb;border-radius:9px;padding:10px 16px;color:inherit}button[aria-pressed=true],.primary{background:#30352f;color:#fffefb;border-color:#30352f}a{color:inherit;text-decoration:none}header{max-width:1080px;margin:auto;padding:30px 32px 16px;display:flex;align-items:center;justify-content:space-between}.wordmark{font:600 29px Georgia,serif;letter-spacing:-1px}.wordmark span{color:#a7482b}.back{font-size:12px;color:#61625a}main{max-width:1000px;padding:10px 32px 48px;margin:auto}.intro{text-align:center;margin-bottom:15px}.eyebrow{font-size:10px;letter-spacing:.19em;color:#a7482b}.intro h1{font:400 34px "Songti SC",Georgia,serif;margin:12px 0}.intro p{font-size:13px;line-height:1.8;color:#65665e;margin:0}.stage{border:1px solid #e4ded4;background:#fffefb;border-radius:24px;padding:0 24px 23px;overflow:hidden}.stage-button{display:block;padding:0;margin:0 auto;border:0;background:none;cursor:pointer}.stage-button:focus-visible{outline-offset:-20px}#logo-root{--mark-size:336px;display:block;width:336px;height:336px;max-width:78vw;max-height:78vw;margin:6px auto 0}#logo-root [data-part]{transition-duration:650ms}.stage-meta{display:flex;align-items:center;justify-content:center;gap:9px;color:#73746b;font-size:11px;margin:0 0 20px}.stage-meta i{height:5px;width:5px;border-radius:50%;background:#b36342}.controls{display:flex;align-items:center;justify-content:center;gap:9px;flex-wrap:wrap}.controls button{font-size:12px}.tuner{display:flex;align-items:center;gap:10px;font-size:11px;color:#62645c}.tuner input{accent-color:#a7482b;width:108px}.timeline{max-width:520px;margin:22px auto 0;display:flex;align-items:center;gap:12px;font-size:10px;color:#6c6f65;font-variant-numeric:tabular-nums}.timeline input{flex:1;accent-color:#a7482b}.principles{display:flex;justify-content:center;gap:8px;flex-wrap:wrap;margin:15px 0 0;font-size:10px;color:#63665d}.principles span{padding:5px 8px;background:#f4f1eb;border-radius:6px}.studies{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;margin-top:19px}.study{padding:18px 12px 17px;text-align:center;border:1px solid #e4ded4;border-radius:16px;background:#fffefb}.study .morning-logo{--mark-size:128px}.study button.morning-logo{border:0;padding:0}.study h2{font-size:12px;font-weight:550;margin:3px 0 7px}.study p{font-size:11px;color:#72756a;margin:0;line-height:1.6}.layers{margin-top:32px}.layers-head{display:flex;align-items:baseline;justify-content:space-between;gap:12px}.layers-head h2{font-size:15px;font-weight:550}.layers-head span{font-size:11px;color:#62665b}.layer-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:13px}.layer{display:flex;flex-direction:column;align-items:center;justify-content:center;border:1px solid #dfdbd2;border-radius:12px;background:#ebe6dc;padding:15px 8px;font-size:12px;cursor:pointer}.layer .morning-logo{--mark-size:110px;width:100%;height:112px}.layer input{accent-color:#a7482b}.layer>span{display:flex;gap:8px;align-items:center}.layer:has(input:not(:checked)) .morning-logo{opacity:.38}.layer small{font-size:10px;color:#74786a;margin-top:7px}footer{font-size:11px;color:#6c6e64;text-align:center;margin-top:26px;line-height:1.8}body.qa{background:#fffefb}body.qa header,body.qa .intro,body.qa .stage-meta,body.qa .controls,body.qa .timeline,body.qa .principles,body.qa .studies,body.qa .layers,body.qa footer{display:none}body.qa main{padding:0;max-width:none}body.qa .stage{border:0;background:#fffefb;border-radius:0;padding:0;overflow:visible}body.qa #logo-root{margin:0;max-width:none;max-height:none}.is-static [data-enter]{animation:none!important;transform:none!important;opacity:1!important}@media(max-width:640px){header{padding:23px 22px 10px}main{padding:10px 16px 30px}.intro h1{font-size:29px}.stage{padding:0 8px 20px;border-radius:18px}.studies{gap:8px}.study{padding:12px 5px}.study .morning-logo{--mark-size:95px}.layer-grid{grid-template-columns:repeat(2,1fr)}.layers-head span{max-width:50%;text-align:right}.controls{gap:7px}.controls button{padding:9px 12px}.tuner{margin-top:5px}.timeline{margin:18px 12px 0}.principles{gap:4px}.principles span{font-size:9px}}
__CSS__
</style></head><body>
<header><a class="wordmark" id="back-home" href="/">morning<span>.</span></a><a class="back" id="back-app" href="/">返回 Morning ↗</a></header>
<main><div class="intro"><span class="eyebrow">ONE MARK · FOUR LAYERS</span><h1>层叠日出。</h1><p>太阳升起，曲面相合。每一层都能独立运动。</p></div>
<section class="stage" aria-label="Logo 动效预览"><button class="stage-button" id="replay-stage" aria-label="重播分层 Logo"><div id="logo-root" class="morning-logo is-intro" aria-hidden="true" data-p2m-duration="1600"></div></button>
<div class="stage-meta"><i></i><span id="state-label">启动 · 分层聚合</span></div>
<div class="controls"><button class="primary" id="replay">重播</button><button id="play" aria-pressed="false">暂停</button><button id="explode" aria-pressed="false">分层展开</button><button id="slow" aria-pressed="false">慢动作</button><label class="tuner">速度<input id="speed" aria-label="播放速度" type="range" min="0.2" max="1.5" step="0.1" value="1"><output id="speed-value">1×</output></label></div>
<label class="timeline"><span>进度</span><input id="time" aria-label="动画进度" type="range" min="0" max="1600" step="1" value="0"><output id="time-value">0 ms</output></label>
<div class="principles"><span>前后层次</span><span>错峰进入</span><span>柔和缓动</span><span>轻微收稳</span><span>完整独立几何</span></div></section>
<section class="studies" aria-label="不同状态"><article class="study"><button class="morning-logo is-interactive" id="hover-study" aria-label="体验悬停分层反馈"></button><h2>轻轻展开</h2><p>悬停或键盘聚焦</p></article><article class="study"><div class="morning-logo is-active" id="live-study" aria-hidden="true"></div><h2>正在工作</h2><p>图层错峰，底座稳定</p></article><article class="study"><button class="morning-logo is-intro" id="intro-study" aria-label="重播启动动效"></button><h2>重新醒来</h2><p>点击重播组装过程</p></article></section>
<section class="layers" aria-labelledby="layers-title"><div class="layers-head"><h2 id="layers-title">四层，分别完整。</h2><span>切换图层，查看遮挡后的形状</span></div><div class="layer-grid" id="layer-grid"></div></section>
<footer>这一枚图形用于品牌区、头像、输入框、启动画面和浏览器图标。<br>跟随系统的减少动态效果设置。</footer></main>
<script>
const SVG_TEXT=__SVG_JSON__;
const DURATION=1600, root=document.querySelector('#logo-root'), time=document.querySelector('#time'), timeValue=document.querySelector('#time-value');
const reduced=matchMedia('(prefers-reduced-motion: reduce)'), query=new URLSearchParams(location.search);
let playing=true, rate=1, expanded=false, frame=0;
function build(target, namespace){target.innerHTML=SVG_TEXT.replaceAll('ml-',namespace+'-');target.querySelector('svg').setAttribute('aria-hidden','true');}
function animations(target=root){return target.getAnimations({subtree:true}).filter(animation=>animation instanceof CSSAnimation);}
function finalPose(){playing=false;document.querySelector('#play').textContent='播放';for(const animation of animations())animation.finish();root.classList.add('is-static');time.value=DURATION;timeValue.textContent=DURATION+' ms';}
function seek(ms){root.classList.remove('is-static');for(const animation of animations()){animation.pause();animation.currentTime=ms;animation.playbackRate=rate;}time.value=ms;timeValue.textContent=ms+' ms';if(ms>=DURATION)finalPose();playing=false;document.querySelector('#play').textContent='播放';}
function replay(){expanded=false;root.classList.remove('is-exploded','is-static');document.querySelector('#explode').setAttribute('aria-pressed','false');document.querySelector('#state-label').textContent='启动 · 分层聚合';build(root,'hero');for(const checkbox of document.querySelectorAll('.layer input'))checkbox.checked=true;for(const animation of animations()){animation.currentTime=0;animation.playbackRate=rate;animation.play();}playing=true;document.querySelector('#play').textContent='暂停';if(reduced.matches)finalPose();else if(!frame)frame=requestAnimationFrame(tick);}
build(root,'hero');build(document.querySelector('#hover-study'),'hover');build(document.querySelector('#live-study'),'live');build(document.querySelector('#intro-study'),'intro');
const views={sun:'235 170 810 780',rear:'145 440 1040 450',front:'85 540 1000 345',base:'155 752 940 325'};
for(const [part,label] of [['sun','太阳'],['rear','后层片'],['front','前层片'],['base','底座']]){
 const tile=document.createElement('label');tile.className='layer';const icon=document.createElement('div');icon.className='morning-logo';icon.setAttribute('aria-hidden','true');build(icon,'solo-'+part);icon.querySelector('svg').setAttribute('viewBox',views[part]);for(const layer of icon.querySelectorAll('[data-part]'))if(layer.dataset.part!==part)layer.style.display='none';icon.querySelector('[data-sun-window]').removeAttribute('clip-path');
 const line=document.createElement('span'),checkbox=document.createElement('input');checkbox.type='checkbox';checkbox.checked=true;checkbox.setAttribute('aria-label','显示'+label);checkbox.addEventListener('change',()=>{finalPose();root.querySelector('[data-part="'+part+'"]').style.display=checkbox.checked?'':'none';if(part==='base')root.querySelector('[data-part=shadow]').style.display=checkbox.checked?'':'none';});line.append(checkbox,document.createTextNode(label));tile.append(icon,line);document.querySelector('#layer-grid').append(tile);
}
root.addEventListener('animationend',event=>{if(event.animationName==='logo-sun-enter')finalPose();});
document.querySelector('#replay').onclick=replay;document.querySelector('#replay-stage').onclick=replay;
document.querySelector('#intro-study').onclick=()=>build(document.querySelector('#intro-study'),'intro');
document.querySelector('#play').onclick=()=>{if(root.classList.contains('is-static')||expanded){replay();return;}root.classList.remove('is-static');playing=!playing;for(const animation of animations()){if(Number(animation.currentTime)>=DURATION)animation.currentTime=0;playing?animation.play():animation.pause();}document.querySelector('#play').textContent=playing?'暂停':'播放';document.querySelector('#play').setAttribute('aria-pressed',String(!playing));if(playing&&!frame)frame=requestAnimationFrame(tick);};
document.querySelector('#explode').onclick=()=>{finalPose();expanded=!expanded;root.classList.toggle('is-exploded',expanded);document.querySelector('#explode').setAttribute('aria-pressed',String(expanded));document.querySelector('#state-label').textContent=expanded?'分层 · 四个独立实体':'静态 · 组合后的 Logo';};
function setRate(value){rate=value;document.querySelector('#speed').value=rate;document.querySelector('#speed-value').textContent=rate+'×';for(const animation of document.getAnimations())if(animation instanceof CSSAnimation)animation.playbackRate=rate;}
document.querySelector('#speed').oninput=event=>setRate(Number(event.target.value));
document.querySelector('#slow').onclick=()=>{const slow=document.querySelector('#slow').getAttribute('aria-pressed')!=='true';document.querySelector('#slow').setAttribute('aria-pressed',String(slow));setRate(slow ? .3 : 1);};
time.oninput=()=>seek(Number(time.value));
function tick(){frame=0;if(playing&&!root.classList.contains('is-static')){const current=Number(animations()[0]?.currentTime||0);const t=Math.min(DURATION,Math.max(0,current));time.value=t;timeValue.textContent=Math.round(t)+' ms';if(t<DURATION)frame=requestAnimationFrame(tick);else{playing=false;document.querySelector('#play').textContent='播放';}}}frame=requestAnimationFrame(tick);
if(location.protocol==='file'){for(const id of ['back-home','back-app'])document.querySelector('#'+id).href='http://127.0.0.1:8788/';document.querySelector('link[rel=icon]').href='data:image/svg+xml,'+encodeURIComponent(SVG_TEXT);}
if(query.has('t')||query.has('static')||query.has('qa'))document.body.classList.add('qa');
if(query.get('static')==='1'||reduced.matches)finalPose();else if(query.has('t'))seek(Math.max(0,Math.min(DURATION,Number(query.get('t'))||0)));
if(query.get('explode')==='1'){finalPose();expanded=true;document.querySelector('#explode').setAttribute('aria-pressed','true');document.querySelector('#state-label').textContent='分层 · 四个独立实体';root.classList.add('is-exploded');for(const part of root.querySelectorAll('[data-part]'))part.style.transition='none';}
window.__p2mReady=true;
</script></body></html>"""

output = HTML.replace("__CSS__", CSS).replace("__SVG_JSON__", json.dumps(SVG, ensure_ascii=False).replace("</", "<\\/"))
for destination in (ROOT / "apps/pulse/public/logo-motion.html", ROOT / "docs/design/morning/logo_motion.html"):
    destination.write_text(output)
(ROOT / "docs/design/morning/motion.css").write_text(CSS)
(ROOT / "docs/design/morning/logo.svg").write_text(SVG)
(ROOT / "apps/pulse/public/mark.svg").write_text(
    SVG.replace('width="480" height="480" viewBox="0 0 1254 1254"', 'width="64" height="64" viewBox="90 200 1080 900"')
)
print("Layered logo preview regenerated from the product SVG and CSS.")
